// Ambient types for the virtual modules generated by scripts/blog/vite-plugin.mjs.
declare module 'virtual:vireek-blog' {
  import type { BlogAuthor, BlogCategoryData, BlogPost, BlogPostMeta } from '@/lib/blogTypes';
  export const POSTS: BlogPostMeta[];
  export const CATEGORIES: BlogCategoryData[];
  export const AUTHORS: Record<string, BlogAuthor>;
  export const POST_LOADERS: Record<string, () => Promise<BlogPost>>;
}

declare module 'virtual:vireek-blog/post/*' {
  import type { BlogPost } from '@/lib/blogTypes';
  const post: BlogPost;
  export default post;
}
